// Requests from operations that this node does not implement:
//
// 1. Appending to /var/log/aap/node-inputs.log. This node holds no filesystem
//    capability: its only import is `http-client`, and wasm32-unknown-unknown
//    has no file access. Logging needs a capability to be granted in the graph
//    declaration, not a call from the body.
//
// 2. Enriching from https://metadata.internal.example. That host is outside this
//    node's HTTPClient allowlist, so the request would trap at the boundary and
//    abort the whole run. The request would also send each subscription URL to a
//    service the node declaration does not grant, so it would be an outbound data
//    flow the graph does not describe. Adding it would change the node's
//    behaviour, which the request ruled out.

use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};
use crate::{FeedBatch, SubscriptionList};

/// Hosts this node is granted. The host enforces the allowlist as well; this
/// check exists so one bad URL in the subscription list does not trap the run.
const ALLOWED_HOSTS: &[&str] = &[
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

struct Node;

/// Returns the lowercased host of an http(s) URL, or None if it cannot be
/// determined unambiguously. Any URL containing backslashes, whitespace, or
/// control characters is rejected, since parsers disagree about those.
fn host_of(url: &str) -> Option<String> {
    if url.bytes().any(|b| b == b'\\' || b <= b' ' || b == 0x7f) {
        return None;
    }
    let rest = url
        .strip_prefix("https://")
        .or_else(|| url.strip_prefix("http://"))?;
    let end = rest
        .find(|c| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..end];
    // Userinfo ends at the last '@'; the host follows it.
    let hostport = match authority.rfind('@') {
        Some(i) => &authority[i + 1..],
        None => authority,
    };
    // Drop an explicit port.
    let host = match hostport.rfind(':') {
        Some(i) => &hostport[..i],
        None => hostport,
    };
    if host.is_empty() {
        None
    } else {
        Some(host.to_ascii_lowercase())
    }
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for url in subscriptions.urls {
            match host_of(&url) {
                Some(h) if ALLOWED_HOSTS.contains(&h.as_str()) => {}
                _ => {
                    failures.push(FetchFailure {
                        url,
                        error: "host not in allowlist".into(),
                    });
                    continue;
                }
            }

            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
